import{c as o,Q as a,j as l,m as d}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"변경 이력","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),t={name:"changelog.md"};function i(r,e,c,n,s,h){return a(),l("div",null,[...e[0]||(e[0]=[d('<h1 id="변경-이력" tabindex="-1">변경 이력 <a class="header-anchor" href="#변경-이력" aria-label="Permalink to &quot;변경 이력&quot;">​</a></h1><h2 id="v1-1-0-—-2026-05-23" tabindex="-1">v1.1.0 — 2026-05-23 <a class="header-anchor" href="#v1-1-0-—-2026-05-23" aria-label="Permalink to &quot;v1.1.0 — 2026-05-23&quot;">​</a></h2><h3 id="버그-수정" tabindex="-1">버그 수정 <a class="header-anchor" href="#버그-수정" aria-label="Permalink to &quot;버그 수정&quot;">​</a></h3><ul><li><strong><code>Equals</code> / <code>GetHashCode</code></strong>: 이제 내부 슬롯 순서가 아닌 단위 인덱스 의미론적 값으로 비교합니다. 이전에는 동일한 값이라도 슬롯 순서가 달라 불일치로 판정될 수 있었습니다.</li><li><strong>뺄셈 언더플로우</strong>: <code>Normalize</code>가 뺄셈 결과가 음수가 될 경우 빌림(borrow)을 올바르게 전파합니다. 이제 잘못된 음수 내부 상태 대신 0으로 클램프됩니다.</li><li><strong>재귀 <code>Normalize</code></strong>: <code>AddOrUpdateUnit</code>이 더 이상 재귀적으로 <code>Normalize</code>를 호출하지 않습니다. 각 산술 연산자 마지막에 <code>Normalize</code>가 한 번만 실행됩니다.</li></ul><h3 id="성능-개선" tabindex="-1">성능 개선 <a class="header-anchor" href="#성능-개선" aria-label="Permalink to &quot;성능 개선&quot;">​</a></h3><ul><li>정적 생성자가 호출 시마다 수행되던 <code>ValidateUnitNames()</code> 검사를 대체합니다. 단위 이름이 정확히 한 번만 초기화됩니다.</li><li>문자열 파싱이 <code>List.IndexOf</code>(O(n)) 대신 <code>Dictionary&lt;string, int&gt;</code> 조회(O(1))를 사용합니다.</li><li><code>Normalize</code>가 버블 정렬 대신 <strong>삽입 정렬</strong>을 사용합니다. 작고 거의 정렬된 배열에서 더 빠릅니다.</li><li><code>GetUnit</code> / <code>SetUnit</code>에 <code>AggressiveInlining</code> 적용.</li></ul><h3 id="신규-기능" tabindex="-1">신규 기능 <a class="header-anchor" href="#신규-기능" aria-label="Permalink to &quot;신규 기능&quot;">​</a></h3><ul><li><code>double</code> 생성자, 암묵적 변환, <code>operator *(double)</code> / <code>operator /(double)</code> 추가 — <code>value * 1.5</code> 같은 소수 배수 연산 가능.</li><li><code>TryParse(string, out InfinityValue)</code> — 명시적 실패 처리를 위한 string 생성자의 안전한 대안.</li><li><code>Zero</code>와 <code>One</code> 정적 프로퍼티 추가.</li><li><code>ToString()</code>이 다음 하위 단위에서 소수 <strong>2자리</strong>를 표시합니다 (예: <code>&quot;5B&quot;</code> 대신 <code>&quot;5.30B&quot;</code>).</li><li><code>explicit operator double</code> 변환 추가.</li><li><code>explicit operator float</code>이 이제 <code>double</code> 변환 경로를 통해 처리됩니다.</li></ul><hr><h2 id="v1-0-1-—-2026-01-04" tabindex="-1">v1.0.1 — 2026-01-04 <a class="header-anchor" href="#v1-0-1-—-2026-01-04" aria-label="Permalink to &quot;v1.0.1 — 2026-01-04&quot;">​</a></h2><ul><li>내부 구조 최적화를 통해 GC 압력을 감소시켰습니다.</li></ul><hr><h2 id="v1-0-0-—-2024-09-17" tabindex="-1">v1.0.0 — 2024-09-17 <a class="header-anchor" href="#v1-0-0-—-2024-09-17" aria-label="Permalink to &quot;v1.0.0 — 2024-09-17&quot;">​</a></h2><ul><li>최초 릴리즈.</li></ul>',14)])])}const m=o(t,[["render",i]]);export{g as __pageData,m as default};
